package thaumcraft.datagen;

import com.google.gson.*;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** JSON/resource checks only: no registries, client, world or entity construction. */
class Mob8BossAssetsTest {
    private static Map<String,JsonObject> payloads(){Map<String,JsonObject> map=new HashMap<>();for(var entry:TCMob8BossAssetsProvider.read().getAsJsonArray("entries")){var row=entry.getAsJsonObject();map.put(row.get("path").getAsString(),row.getAsJsonObject("payload"));}return map;}
    private static JsonObject json(String path)throws IOException{try(var stream=Mob8BossAssetsTest.class.getClassLoader().getResourceAsStream(path)){assertNotNull(stream,path);return JsonParser.parseString(new String(stream.readAllBytes(),StandardCharsets.UTF_8)).getAsJsonObject();}}
    @Test void sixNativeBlocksHaveThirtyTwoReproducibleSnapshots()throws IOException{var manifest=TCMob8BossAssetsProvider.read();assertEquals(6,manifest.getAsJsonArray("blocks").size());assertEquals(32,manifest.getAsJsonArray("entries").size());for(var row:manifest.getAsJsonArray("entries")){var entry=row.getAsJsonObject();assertEquals(entry.get("payload"),json("assets/thaumcraft/"+entry.get("path").getAsString()));}}
    @Test void sourceRandomWeightsAndRotationsArePreserved(){var map=payloads();var crust=map.get("blockstates/taint_crust.json").getAsJsonObject("variants").getAsJsonArray("");var soil=map.get("blockstates/taint_soil.json").getAsJsonObject("variants").getAsJsonArray("");assertEquals(12,crust.size());assertEquals(12,soil.size());int crustWeight=0,soilWeight=0;for(var row:crust)crustWeight+=row.getAsJsonObject().has("weight")?row.getAsJsonObject().get("weight").getAsInt():1;for(var row:soil)soilWeight+=row.getAsJsonObject().has("weight")?row.getAsJsonObject().get("weight").getAsInt():1;assertEquals(40,crustWeight);assertEquals(72,soilWeight);}
    @Test void allFacingAndAxisStatesResolveActualModels(){var map=payloads();var feature=map.get("blockstates/taint_feature.json").getAsJsonObject("variants");assertEquals(6,feature.size());for(String face:List.of("up","down","north","south","east","west"))assertTrue(feature.has("facing="+face));var log=map.get("blockstates/taint_log.json").getAsJsonObject("variants");assertEquals(3,log.size());for(String axis:List.of("x","y","z"))assertEquals(8,log.getAsJsonArray("axis="+axis).size());for(var payload:map.entrySet())if(payload.getKey().startsWith("blockstates/"))for(var variants:payload.getValue().getAsJsonObject("variants").entrySet())for(var row:variants.getValue().getAsJsonArray()){String model=row.getAsJsonObject().get("model").getAsString();assertTrue(map.containsKey("models/block/"+model.substring("thaumcraft:block/".length())+".json"),model);}}
    @Test void modelTexturesAndItemParentsResolveNativePaths(){var map=payloads();for(var row:map.entrySet()){JsonObject model=row.getValue();if(row.getKey().startsWith("models/item/")){String parent=model.get("parent").getAsString();assertTrue(map.containsKey("models/block/"+parent.substring("thaumcraft:block/".length())+".json"));}if(model.has("textures"))for(var texture:model.getAsJsonObject("textures").entrySet()){String location=texture.getValue().getAsString();if(location.startsWith("#"))continue;assertTrue(location.startsWith("thaumcraft:block/"));assertNotNull(getClass().getClassLoader().getResource("assets/thaumcraft/textures/"+location.substring("thaumcraft:".length())+".png"),location);}}}
    @Test void geometryManifestCoversEveryOwnedEntityAndLiteralSourceModels()throws IOException{var manifest=json("assets/thaumcraft/porting/mob8_boss_geometry.json");assertEquals(13,manifest.getAsJsonArray("presentations").size());Set<String> ids=new HashSet<>();for(var entry:manifest.getAsJsonArray("presentations")){var row=entry.getAsJsonObject();assertTrue(ids.add(row.get("id").getAsString()));String texture=row.get("texture").getAsString();if(texture.startsWith("thaumcraft:"))assertNotNull(getClass().getClassLoader().getResource("assets/thaumcraft/"+texture.substring("thaumcraft:".length())),texture);}assertEquals(4,manifest.getAsJsonArray("geometry").size());var golem=manifest.getAsJsonArray("geometry").get(0).getAsJsonObject();assertEquals(36,golem.get("box_calls").getAsInt());assertEquals(8,golem.get("child_calls").getAsInt());assertTrue(golem.get("sha256_utf8").getAsString().matches("[0-9a-f]{64}"));}
    @Test void malformedAssetPathsAndDuplicateOutputsAreRejected(){var manifest=TCMob8BossAssetsProvider.read().deepCopy();manifest.getAsJsonArray("entries").add(manifest.getAsJsonArray("entries").get(0).deepCopy());assertThrows(IllegalArgumentException.class,()->TCMob8BossAssetsProvider.validate(manifest));var traversal=TCMob8BossAssetsProvider.read().deepCopy();traversal.getAsJsonArray("entries").get(0).getAsJsonObject().addProperty("path","../bad.json");assertThrows(IllegalArgumentException.class,()->TCMob8BossAssetsProvider.validate(traversal));}
}
